svg.script:
document.addEventListener('DOMContentLoaded', () => {
  const teeth = document.querySelectorAll('.tooth');
  teeth.forEach(tooth => {
    tooth.addEventListener('click', () => {
      const id = tooth.getAttribute('data-id');
      // Cycle through states
      const states = ['Healthy', 'Cavity', 'Filling', 'Crown'];
      const currentIndex = states.indexOf(tooth.getAttribute('data-state') || 'Healthy');
      const nextIndex = (currentIndex + 1) % states.length;
      tooth.setAttribute('data-state', states[nextIndex]);
      tooth.style.fill = {
        'Healthy': '#4CAF50',
        'Cavity': '#F44336',
        'Filling': '#2196F3',
        'Crown': '#FFD700'
      }[states[nextIndex]];
    });
  });
});
